#!/usr/bin/env python3
"""The Tatung Einstein build's generated files (docs/port_einstein.md).

The Einstein assembles the same src/main.asm with -DEINSTEIN and
build/einstein on the include path, so these files stand in for their
Spectrum namesakes in build/. Two steps, either side of assembling the
stage packs:

  make_einstein.py gen [stages.yaml] [out dir]
    packs.asm         THEME_CACHE, PANO_CACHE, TRACK_CACHE for the
                      Einstein's memory map (the packs themselves are on
                      the disc)
    stagepacks.asm    every theme and track pack, each assembled where it
                      runs, to theme_*.bin and track_*.bin (sjasmplus)
    art_*.bin         every stage's art
    stageov_pack.asm  (the overlay is resident: a placeholder)
    music_notes.asm   the tone periods for the Einstein's 2 MHz AY

  make_einstein.py dat [stages.yaml] [out dir]
    stages_raw.dat    the packs and the title and goal pictures, each from a
                      128-byte record of its own; room for the front end and
                      the between-stages overlay
    stages.asm        the stage table in the Spectrum's layout (16 bytes a
                      stage), its pack entries (first record in STAGES.DAT,
                      length) where the Spectrum has (bank, address,
                      length); the art table and FrontEndPack likewise
    stageov_pack.asm  StageOvPack: the overlay's (src/stage.asm reads it
                      back after the front end has drawn over it)
    screens_data.asm  the pictures' (records, first record), the endings
    reserve.txt       where the front end and the overlay go

  make_einstein.py patch [stages.yaml] [out dir]
    STAGES.DAT        stages_raw.dat with frontend.bin and stageov.bin
                      (assembled with the game) in their room
"""
import os
import sys

import yaml

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import make_music                           # noqa: E402
import make_stages                          # noqa: E402

AY_CLOCK = 2000000                          # the Einstein's AY (Albert: ay38910.h)
THEME_CACHE = 0x0120                        # after the COM file's jump at $0100
CAPACITY = make_stages.PANO_CACHE - make_stages.THEME_CACHE
PANO_CACHE = (THEME_CACHE + CAPACITY) & ~31
EIN_CODE = PANO_CACHE + 1024                # the platform code (src/einstein/platform.asm)
RECORD = 128


def db_bytes(lines):
    out = []
    for line in lines:
        text = line.strip()
        assert text.startswith("db "), text
        out += [int(v) for v in text[3:].split(",")]
    return bytes(out)


def gen(cfg, outdir):
    packs, stages, art_sizes = make_stages.stage_packs(cfg)
    open(os.path.join(outdir, "packs.asm"), "w").write("\n".join([
        "; Generated by tools/make_einstein.py - do not edit",
        f"PANO_CACHE EQU ${PANO_CACHE:04X}", f"THEME_CACHE EQU ${THEME_CACHE:04X}",
        f"TRACK_CACHE EQU ${make_stages.TRACK_CACHE:04X}", f"EIN_CODE EQU ${EIN_CODE:04X}"]) + "\n")
    out = ["; Generated by tools/make_einstein.py - do not edit",
           f"PANO_CACHE EQU ${PANO_CACHE:04X}", f"THEME_CACHE EQU ${THEME_CACHE:04X}",
           f"TRACK_CACHE EQU ${make_stages.TRACK_CACHE:04X}",
           "; the resident sprites the theme packs name (src/main.asm: at SCN_DATA)",
           "        ORG $5B00", '        INCLUDE "resident_data.asm"']
    for label, lines, size, cache in packs:
        if label.startswith("art_"):
            open(os.path.join(outdir, label + ".bin"), "wb").write(db_bytes(lines))
            continue
        top = "PANO_CACHE" if label.startswith("theme_") else "$8000"
        if label.startswith("theme_"):
            cache = THEME_CACHE             # (the Spectrum's is $DB00)
        out += [f'        OUTPUT "{outdir}/{label}.bin"', f"        ORG ${cache:04X}"] + lines + \
               [f"        ASSERT $ <= {top}", "        OUTEND"]
    open(os.path.join(outdir, "stagepacks.asm"), "w").write("\n".join(out) + "\n")

    make_music.AY_CLOCK = AY_CLOCK
    p = make_music.periods()
    notes = ["; Generated by tools/make_einstein.py - do not edit (the AY at 2 MHz)"]
    for i in range(0, len(p), 8):
        notes.append("        dw " + ", ".join(str(v) for v in p[i:i + 8]))
    open(os.path.join(outdir, "music_notes.asm"), "w").write("\n".join(notes) + "\n")


def dat(cfg, outdir):
    packs, stages, art_sizes = make_stages.stage_packs(cfg)
    data = bytearray()
    where = {}                              # label -> (first record, bytes)
    for label, _, _, _ in packs:
        blob = open(os.path.join(outdir, label + ".bin"), "rb").read()
        records = (len(blob) + RECORD - 1) // RECORD
        where[label] = (len(data) // RECORD, len(blob))
        data += blob + bytes(records * RECORD - len(blob))
    pics = {}                               # the title and goal pictures
    shots = make_stages.make_screens.build(make_stages.make_screens.ending_themes(cfg),
                                           preview_dir=outdir)   # (not assets/: the Spectrum's)
    for name, (raw, packed) in shots.items():
        records = (len(packed) + RECORD - 1) // RECORD
        pics["scr_" + name] = (len(data) // RECORD, records)
        data += packed + bytes(records * RECORD - len(packed))
    room = {}                               # the front end and the overlay: patched in
    for name, size in (("frontend", make_stages.FRONTEND_RESERVE), ("stageov", make_stages.STAGEOV_RESERVE)):
        assert size % RECORD == 0
        room[name] = (len(data) // RECORD, size)
        data += bytes(size)
    open(os.path.join(outdir, "stages_raw.dat"), "wb").write(data)
    open(os.path.join(outdir, "reserve.txt"), "w").write(
        "".join(f"{k} {v[0]} {v[1]}\n" for k, v in room.items()))

    rows = cfg["rows"]
    idx = {(st["row"], st["col"]): i for i, st in enumerate(stages)}
    tab = ["; Generated by tools/make_einstein.py - do not edit",
           f"NUM_STAGES EQU {len(stages)}", f"NUM_ROWS EQU {len(rows)}",
           f"PANO_H EQU {make_stages.PANO_H}", "STAGE_SIZE EQU 16",
           "StageTable:                 ; (theme and track: first record in STAGES.DAT, bytes)"]
    for st in stages:
        r, k = st["row"], st["col"]
        left = idx.get((r + 1, k), 0xFF)
        right = idx.get((r + 1, k + 1), 0xFF)
        th, tr = where[st["theme"]], where[st["track"]]
        tab += [f"        db 0", f"        dw {th[0]}, {th[1]}", f"        db 0", f"        dw {tr[0]}, {tr[1]}",
                f"        db {left}, {right}, {r + 1}", f"        dw {st['par']}", "        db 0"]
    tab.append("RoundArtTable:")
    for st in stages:
        a = where[st["art"]]
        tab.append(f"        db 0")
        tab.append(f"        dw {a[0]}, {a[1]}")
    tab.append("DashHeader:")
    header = make_stages.round_art.dash_header()
    for y in range(8):
        tab.append("        db " + ", ".join(map(str, header[y * 32:(y + 1) * 32])))
    tab += ["FrontEndPack:   db 0", f"        dw {room['frontend'][0]}, {room['frontend'][1]}"]
    open(os.path.join(outdir, "stages.asm"), "w").write("\n".join(tab) + "\n")
    open(os.path.join(outdir, "stageov_pack.asm"), "w").write("\n".join([
        "; Generated by tools/make_einstein.py - do not edit",
        "StageOvPack:                ; (first record in STAGES.DAT, length)",
        "        db 0", f"        dw {room['stageov'][0]}, {room['stageov'][1]}"]) + "\n")
    sd = make_stages.screens_data(cfg, stages, lambda n: (str(pics[n][1]), str(pics[n][0])))
    sd[0] = "; Generated by tools/make_einstein.py - do not edit (pictures: records, first record)"
    open(os.path.join(outdir, "screens_data.asm"), "w").write("\n".join(sd) + "\n")
    print(f"STAGES.DAT: {len(data)} bytes, {len(data) // RECORD} records, {len(packs)} packs")


def patch(cfg, outdir):
    data = bytearray(open(os.path.join(outdir, "stages_raw.dat"), "rb").read())
    for line in open(os.path.join(outdir, "reserve.txt")):
        name, first, size = line.split()
        blob = open(os.path.join(outdir, name + ".bin"), "rb").read()
        if len(blob) > int(size):
            raise SystemExit(f"{name}.bin: {len(blob)} bytes, its room in STAGES.DAT {size}")
        at = int(first) * RECORD
        data[at:at + len(blob)] = blob
    open(os.path.join(outdir, "STAGES.DAT"), "wb").write(data)


def einstein_palettes(cfg):
    """Each theme's and stage's einstein_palette over its palette (the
    TMS9129's colours: see assets/stages.yaml)."""
    for theme in cfg["themes"].values():
        theme["palette"].update(theme.get("einstein_palette", {}))
    for row in cfg["rows"]:
        for stage in row:
            if "einstein_palette" in stage:
                stage["palette"] = {**stage.get("palette", {}), **stage["einstein_palette"]}
    return cfg


def main(step, src="assets/stages.yaml", outdir="build/einstein"):
    os.makedirs(outdir, exist_ok=True)
    cfg = einstein_palettes(yaml.safe_load(open(src))) if step != "patch" else None
    {"gen": gen, "dat": dat, "patch": patch}[step](cfg, outdir)


if __name__ == "__main__":
    main(*sys.argv[1:4])
